import os
import requests

BASE_URL = os.getenv("SOCBENCH_API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", **kwargs)
    response.raise_for_status()
    if response.content:
        return response.json()
    return None

materials = request("GET", "/materials") or []
classified_materials = []

for material in materials:
    classification = request("POST", "/materials/classify", json={"material": material})
    item = {"material": material, "classification": classification}

    material_id = material.get("id")
    requires_compliance = (
        classification.get("requiresComplianceCheck", False)
        or classification.get("complianceRequired", False)
    )

    if material_id is not None and requires_compliance:
        item["compliance"] = request(
            "GET", f"/materials/{material_id}/compliance"
        )

        calculation_id = (
            item["compliance"].get("calculationId")
            if isinstance(item["compliance"], dict)
            else None
        )
        if calculation_id:
            item["compliance_calculation_result"] = request(
                "GET", f"/calculations/{calculation_id}/result"
            )

    classified_materials.append(item)

for item in classified_materials:
    material = item["material"]
    request(
        "PATCH",
        "/logistics/route",
        json={
            "materialId": material.get("id"),
            "classification": item["classification"],
            "compliance": item.get("compliance"),
            "complianceCalculationResult": item.get(
                "compliance_calculation_result"
            ),
        },
    )

inventory_status = request("GET", "/inventory/status")

maintenance_schedule = {
    "equipmentId": os.getenv("EQUIPMENT_ID", "processing-machinery"),
    "schedule": {
        "reason": "Routine maintenance for machinery processing classified materials",
        "materials": [
            item["material"].get("id") for item in classified_materials
        ],
    },
}
request("POST", "/equipment/maintenance-schedule", json=maintenance_schedule)

resource_usage_statistics = request("GET", "/analysis/statistics")

results = {
    "classified_materials": classified_materials,
    "inventory_status": inventory_status,
    "resource_usage_statistics": resource_usage_statistics,
}

