import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})

def register_patient(patient_details):
    response = session.post(f"{BASE_URL}/patients", json=patient_details)
    response.raise_for_status()
    return response.json()

def get_upcoming_consultations(patient_id):
    response = session.get(
        f"{BASE_URL}/patients/{patient_id}/scheduled-consultations"
    )
    response.raise_for_status()
    return response.json()

def validate_insurance(policy_details):
    response = session.post(f"{BASE_URL}/policies/validate", json=policy_details)
    response.raise_for_status()
    return response.json()

def securely_share_medical_data(exchange_details):
    response = session.post(
        f"{BASE_URL}/secure-data-exchange",
        json=exchange_details,
    )
    response.raise_for_status()
    return response.json()

def register_patient_and_prepare_treatment(
    patient_details,
    policy_details,
    provider_id,
    medical_data,
):
    patient = register_patient(patient_details)
    patient_id = patient.get("id") or patient.get("patient_id")
    if not patient_id:
        raise ValueError("Patient creation response did not include a patient ID")

    consultations = get_upcoming_consultations(patient_id)

    coverage_request = {
        **policy_details,
        "patient_id": patient_id,
    }
    coverage = validate_insurance(coverage_request)

    exchange_request = {
        "patient_id": patient_id,
        "provider_id": provider_id,
        "medical_data": medical_data,
    }
    exchange = securely_share_medical_data(exchange_request)

    return {
        "patient": patient,
        "upcoming_consultations": consultations,
        "insurance_coverage": coverage,
        "secure_data_exchange": exchange,
    }

# Supply the patient's full details, insurance policy details, provider ID,
# and medical data. Call again with another patient's details if needed.
result = register_patient_and_prepare_treatment(
    patient_details=patient_details,
    policy_details=policy_details,
    provider_id=provider_id,
    medical_data=medical_data,
)

