# Use the available threat and equipment records to identify relevant software
# patches. Only create software records when the API data explicitly provides
# patch details associated with an equipment item and threat.
def records(value):
    if isinstance(value, list):
        return value
    if isinstance(value, dict):
        for key in ("items", "data", "results"):
            if isinstance(value.get(key), list):
                return value[key]
    return []

installed_records = records(installed_software)
threat_records = records(threats)
equipment_records = records(equipment)

def normalized(value):
    return str(value).strip().lower() if value is not None else ""

for item in equipment_records:
    equipment_id = item.get("id")
    if equipment_id is None:
        continue

    detail_response = session.get(f"{BASE_URL}/equipment/{equipment_id}")
    detail_response.raise_for_status()
    equipment_detail = detail_response.json()

    equipment_text = " ".join(
        normalized(equipment_detail.get(key, item.get(key)))
        for key in ("id", "name", "type", "model", "manufacturer", "description")
    )

    for threat in threat_records:
        threat_text = " ".join(
